import{_ as t,o as a,c as o,a3 as n}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"Accounting — User Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Accounting — User Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/accounting"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Accounting — User Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/accounting"}]]},"headers":[],"relativePath":"user-guide/accounting.md","filePath":"user-guide/accounting.md","lastUpdated":1786638276000}'),r={name:"user-guide/accounting.md"};function i(l,e,s,c,d,u){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="accounting-—-user-guide" tabindex="-1">Accounting — User Guide <a class="header-anchor" href="#accounting-—-user-guide" aria-label="Permalink to &quot;Accounting — User Guide&quot;">​</a></h1><p>Enable <strong>Accounting</strong> from Marketplace (free). Nav appears under <strong>Finance</strong>: Accounts, Journals, General Ledger.</p><h2 id="chart-of-accounts" tabindex="-1">Chart of accounts <a class="header-anchor" href="#chart-of-accounts" aria-label="Permalink to &quot;Chart of accounts&quot;">​</a></h2><ol><li>Open <strong>Accounts</strong>. A starter chart loads automatically the first time.</li><li>Use <strong>New account</strong> to add custom codes (code, name, type).</li><li>System accounts cannot be deleted or renumbered; accounts with posted journal lines cannot be deleted.</li><li>Soft-deleted custom accounts can be restored (or permanently deleted) via the trash filter when you have restore / force-delete permission.</li></ol><h2 id="journals" tabindex="-1">Journals <a class="header-anchor" href="#journals" aria-label="Permalink to &quot;Journals&quot;">​</a></h2><ol><li>Open <strong>Journals</strong> → <strong>New journal</strong>.</li><li>Set the entry date and memo.</li><li>Add at least two lines. Each line needs an account and either a debit or a credit (not both).</li><li>Debits must equal credits before you can save.</li><li>Open the entry → <strong>Post</strong> to make it immutable and visible on the general ledger.</li><li>Posted entries can be <strong>Void</strong> (excluded from GL/reports; reason optional).</li></ol><h2 id="general-ledger" tabindex="-1">General ledger <a class="header-anchor" href="#general-ledger" aria-label="Permalink to &quot;General ledger&quot;">​</a></h2><ol><li>Open <strong>General Ledger</strong>.</li><li>Optionally filter by account and date range → <strong>Apply filters</strong>.</li><li>Review opening/closing balance and paginated line detail for posted journals only.</li></ol><h2 id="related-reports" tabindex="-1">Related reports <a class="header-anchor" href="#related-reports" aria-label="Permalink to &quot;Related reports&quot;">​</a></h2><p>Install <strong>Financial Reports</strong> (requires Accounting) for Trial Balance, Profit &amp; Loss, and Balance Sheet.</p>',10)])])}const p=t(r,[["render",i]]);export{m as __pageData,p as default};
